def solve(p):
    patience = p['patience']
    delta = p['delta']
    if patience < 1 or delta < 0:
        raise ValueError('config')

    supplied = p['state']
    s = dict(supplied) if supplied is not None else {
        'best': None,
        'best_index': -1,
        'stale': 0,
        'seen': 0,
        'stopped': False,
    }
    if s['stopped']:
        return s

    for value in p['values']:
        if s['stopped']:
            break
        s = advance(s, value, s['seen'], patience, delta)
    return s
